**Purpose:** Create engaging social media content for organic posts and thought leadership

**Quote Graphic Template (Instagram/LinkedIn):**

```json
{
  "asset_type": "quote_graphic",
  "platform": "Instagram / LinkedIn",
  "format": {
    "size": "1080x1080px (square)",
    "orientation": "square for versatility"
  },
  "content": {
    "quote": "Design is not just what it looks like. Design is how it works.",
    "attribution": "- Steve Jobs",
    "context": "Technology / Design / Innovation"
  },
  "design_layout": {
    "background": {
      "style": "minimal gradient or solid color",
      "color": "brand colors or thematic colors",
      "alternatives": "subtle texture, abstract shapes, or minimal imagery"
    },
    "quote_text": {
      "content": "Main quote in large, readable font",
      "typography": "serif or elegant sans-serif for readability",
      "size": "large, 60-80pt equivalent",
      "color": "high contrast (white on dark, dark on light)",
      "alignment": "centered or left-aligned based on design",
      "spacing": "generous line spacing for readability"
    },
    "attribution": {
      "content": "Author name",
      "style": "smaller, lighter weight than quote",
      "placement": "below quote, right-aligned or centered",
      "dash_or_em_dash": "use em dash (—) before name"
    },
    "accent_elements": {
      "quotation_marks": "large decorative quote marks (optional)",
      "geometric_shapes": "circles, lines, or minimalist accents",
      "brand_element": "small logo or brand mark (subtle)"
    }
  },
  "color_schemes": {
    "professional": {
      "background": "navy blue (#1A2B4C)",
      "text": "white or cream (#FFFFFF or #F5F5DC)",
      "accent": "gold or teal (#D4AF37 or #00A896)"
    },
    "modern": {
      "background": "gradient (purple to blue)",
      "text": "white (#FFFFFF)",
      "accent": "bright cyan (#00D9FF)"
    },
    "minimal": {
      "background": "off-white (#F8F8F8)",
      "text": "dark gray or black (#333333)",
      "accent": "brand color"
    }
  },
  "technical": {
    "resolution": "1080x1080px",
    "format": "PNG or JPG",
    "text_readability": "test on mobile, ensure high contrast",
    "safe_zone": "keep text in center 920x920px area"
  }
}
```

